#!/bin/sh
# One kith-sched call: $1 is the clock for it (KITH_SCHED_NOW; - leaves it unset), the rest is the verb. The Rust verb
# gets the same line. Waits a moment after: a started run is detached and writes its record on its own.
if [ "$1" != - ]; then KITH_SCHED_NOW=$1; export KITH_SCHED_NOW; fi
shift
if [ "$KITH_CORE" = rust ]; then "$KITH_BIN" kernel schedule "$@"; else python3 "$HOME/k/bin/kith-sched" "$@"; fi
rc=$?
# a started run is detached: wait for each stand-in kith to have written its record (and, unless it is a slow-* one, ended)
python3 - <<'PY'
import json, os, time
try:
    last = json.load(open(os.environ['HOME'] + '/.kith/sched/state.json')).get('last', {})
except (OSError, ValueError):
    last = {}
end = time.time() + 60
for k, v in last.items():
    pid = v.get('pid')
    if not isinstance(pid, int):
        continue
    while time.time() < end and not os.path.exists('%s/.stub/%d' % (os.environ['HOME'], pid)):
        try:
            os.kill(pid, 0)   # gone without a record: a pid out of a fixture, not a run of ours
        except OSError:
            break
        time.sleep(0.02)
    while time.time() < end and not k.split('/')[1].startswith('slow-'):
        try:
            os.kill(pid, 0)
        except OSError:
            break
        time.sleep(0.02)
PY
# a run's outbox is named by the nanosecond it was made in: number them in the order they appeared, per run
python3 - <<'PY'
import glob, os, re
root = os.environ['HOME'] + '/.kith/outbox'
keys = sorted({re.fullmatch(r'(sched-.*?)-(\d{15,})(?:\.json)?', os.path.basename(p)).groups()
               for p in glob.glob(root + '/sched-*') if re.fullmatch(r'(sched-.*?)-(\d{15,})(?:\.json)?', os.path.basename(p))},
              key=lambda k: k[1])
for pre, ns in keys:
    n = 1
    while os.path.exists('%s/%s-n%d' % (root, pre, n)):
        n += 1
    for suf in ('', '.json'):
        if os.path.exists('%s/%s-%s%s' % (root, pre, ns, suf)):
            os.rename('%s/%s-%s%s' % (root, pre, ns, suf), '%s/%s-n%d%s' % (root, pre, n, suf))
PY
exit $rc

